const phrases = [_][]const u8{
    "Step on no pets.",
for (phrases) |phrase| {
    var clean: [100]u8 = undefined;
    var len: usize = 0;
    for (phrase) |c| {
        const lower = std.ascii.toLower(c);
        if (lower >= 'a' and lower <= 'z') {
            clean[len] = lower;
            len += 1;
    var palindrome = true;
    for (0..len / 2) |i| {
        if (clean[i] != clean[len - 1 - i]) {
            palindrome = false;
            break;
    try out.print("{s} -> {s}\n", .{ phrase, if (palindrome) @as([]const u8, "yes") else "no" });
